import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState
} from "react";

import Chart from "chart.js/auto";

import { marketIndices } from "./data";

import "./main.css";
import "./components.css";
import "./animations.css";
import "@fortawesome/fontawesome-free/css/all.min.css";


// ===============================
// API CONFIGURATION
// ===============================

const API_BASE_URL = "http://localhost:5000/api";

const USER_ID = "testuser";


// ===============================
// APP
// ===============================

function App() {
  // -------------------------------
  // STATE
  // -------------------------------

  const [stocks, setStocks] = useState({});

  const [watchlist, setWatchlist] = useState([
    "RELIANCE",
    "TCS",
    "INFY"
  ]);

  const [filters, setFilters] = useState({
    search: "",
    sector: "",
    cap: ""
  });

  const [chartType, setChartType] = useState("line");

  const [theme, setTheme] = useState(
    () => localStorage.getItem("theme") || "dark"
  );

  const [marketStatus, setMarketStatus] = useState("LIVE");

  const [updating, setUpdating] = useState(false);

  const [selectedStock, setSelectedStock] = useState(null);

  const [loading, setLoading] = useState(true);

  const [portfolio, setPortfolio] = useState({
    userId: USER_ID,
    cashBalance: 100000,
    holdings: []
  });

  const [transactions, setTransactions] = useState([]);

  const [tradeLoading, setTradeLoading] = useState(false);

  const [message, setMessage] = useState("");

  const [messageType, setMessageType] = useState("success");


  // ===============================
  // THEME
  // ===============================

  useEffect(() => {
    document.body.className =
      theme === "light" ? "light-theme" : "dark-theme";

    const root = document.documentElement;

    if (theme === "light") {
      root.style.setProperty("--bg-primary", "#ffffff");
      root.style.setProperty("--bg-secondary", "#f8f9fa");
      root.style.setProperty("--bg-tertiary", "#e9ecef");
      root.style.setProperty("--bg-panel", "#ffffff");
      root.style.setProperty("--text-primary", "#212529");
      root.style.setProperty("--text-secondary", "#6c757d");
      root.style.setProperty("--border-color", "#dee2e6");
    } else {
      root.style.setProperty("--bg-primary", "#0a0e1a");
      root.style.setProperty("--bg-secondary", "#1a1f35");
      root.style.setProperty("--bg-tertiary", "#242b42");
      root.style.setProperty("--bg-panel", "#1e2438");
      root.style.setProperty("--text-primary", "#e6e8ef");
      root.style.setProperty("--text-secondary", "#9ca3b4");
      root.style.setProperty("--border-color", "#2d3748");
    }
  }, [theme]);


  // ===============================
  // SHOW MESSAGE
  // ===============================

  const showMessage = (text, type = "success") => {
    setMessage(text);
    setMessageType(type);

    setTimeout(() => {
      setMessage("");
    }, 3500);
  };


  // ===============================
  // FETCH STOCKS
  // ===============================

  const fetchStocks = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/stocks`);

      if (!response.ok) {
        throw new Error("Failed to fetch stocks");
      }

      const data = await response.json();

      const formattedStocks = {};

      data.forEach((stock) => {
        const oldStock = stocks[stock.symbol];

        formattedStocks[stock.symbol] = {
          symbol: stock.symbol,
          name: stock.name,
          price: stock.price,
          change: stock.change,
          changePercent: stock.changePercent,
          volume: stock.volume,
          marketCap: stock.marketCap,
          sector: stock.sector,
          exchange: stock.exchange,
          lastUpdated: stock.lastUpdated,

          // Keep chart history between refreshes
          history: oldStock?.history
            ? [
                ...oldStock.history.slice(-49),
                {
                  time: new Date(stock.lastUpdated).toLocaleTimeString(),
                  price: stock.price,
                  volume: stock.volume
                }
              ]
            : [
                {
                  time: new Date(stock.lastUpdated).toLocaleTimeString(),
                  price: stock.price,
                  volume: stock.volume
                }
              ]
        };
      });

      setStocks(formattedStocks);

      setMarketStatus("LIVE");
    } catch (error) {
      console.error("Stock fetch error:", error);

      setMarketStatus("ERROR");

      showMessage(
        "Unable to connect to the stock API.",
        "error"
      );
    }
  }, [stocks]);


  // ===============================
  // FETCH PORTFOLIO
  // ===============================

  const fetchPortfolio = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/portfolio/${USER_ID}`
      );

      if (!response.ok) {
        throw new Error("Failed to fetch portfolio");
      }

      const data = await response.json();

      setPortfolio(data);
    } catch (error) {
      console.error("Portfolio fetch error:", error);
    }
  }, []);


  // ===============================
  // FETCH TRANSACTIONS
  // ===============================

  const fetchTransactions = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/transactions/${USER_ID}`
      );

      if (!response.ok) {
        throw new Error("Failed to fetch transactions");
      }

      const data = await response.json();

      setTransactions(data);
    } catch (error) {
      console.error("Transaction fetch error:", error);
    }
  }, []);


  // ===============================
  // INITIAL LOAD
  // ===============================

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);

      await Promise.all([
        fetchStocks(),
        fetchPortfolio(),
        fetchTransactions()
      ]);

      setLoading(false);
    };

    loadData();
  }, [fetchPortfolio, fetchStocks, fetchTransactions]);


  // ===============================
  // AUTO REFRESH
  // ===============================

  useEffect(() => {
    const interval = setInterval(() => {
      fetchStocks();
    }, 180000);

    return () => clearInterval(interval);
  }, [fetchStocks]);


  // ===============================
  // MANUAL REFRESH
  // ===============================

  const refresh = async () => {
    if (updating) return;

    setUpdating(true);

    setMarketStatus("UPDATING");

    await fetchStocks();

    setUpdating(false);

    showMessage("Stock data refreshed successfully.");
  };


  // ===============================
  // WATCHLIST
  // ===============================

  const addToWatchlist = (symbol) => {
    setWatchlist((previous) =>
      previous.includes(symbol)
        ? previous
        : [...previous, symbol]
    );
  };


  const removeFromWatchlist = (symbol) => {
    setWatchlist((previous) =>
      previous.filter((item) => item !== symbol)
    );
  };


  // ===============================
  // BUY STOCK
  // ===============================

  const buyStock = async (symbol, quantity) => {
    if (!quantity || quantity <= 0) {
      showMessage(
        "Enter a valid quantity.",
        "error"
      );

      return;
    }

    setTradeLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/transactions/buy`,
        {
          method: "POST",

          headers: {
            "Content-Type": "application/json"
          },

          body: JSON.stringify({
            userId: USER_ID,
            symbol,
            quantity: Number(quantity)
          })
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message || "Purchase failed"
        );
      }

      setPortfolio(data.portfolio);

      await fetchTransactions();

      showMessage(
        `Successfully bought ${quantity} ${symbol} share(s).`
      );
    } catch (error) {
      console.error("BUY error:", error);

      showMessage(
        error.message || "Unable to buy stock.",
        "error"
      );
    } finally {
      setTradeLoading(false);
    }
  };


  // ===============================
  // SELL STOCK
  // ===============================

  const sellStock = async (symbol, quantity) => {
    if (!quantity || quantity <= 0) {
      showMessage(
        "Enter a valid quantity.",
        "error"
      );

      return;
    }

    setTradeLoading(true);

    try {
      const response = await fetch(
        `${API_BASE_URL}/transactions/sell`,
        {
          method: "POST",

          headers: {
            "Content-Type": "application/json"
          },

          body: JSON.stringify({
            userId: USER_ID,
            symbol,
            quantity: Number(quantity)
          })
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message || "Sale failed"
        );
      }

      setPortfolio(data.portfolio);

      await fetchTransactions();

      showMessage(
        `Successfully sold ${quantity} ${symbol} share(s).`
      );
    } catch (error) {
      console.error("SELL error:", error);

      showMessage(
        error.message || "Unable to sell stock.",
        "error"
      );
    } finally {
      setTradeLoading(false);
    }
  };


  // ===============================
  // FILTER STOCKS
  // ===============================

  const filteredStocks = useMemo(() => {
    let list = Object.entries(stocks);

    const term = filters.search.toLowerCase();

    if (term) {
      list = list.filter(([symbol, stock]) =>
        stock.name.toLowerCase().includes(term) ||
        symbol.toLowerCase().includes(term) ||
        stock.sector.toLowerCase().includes(term)
      );
    }

    if (filters.sector) {
      list = list.filter(
        ([, stock]) =>
          stock.sector === filters.sector
      );
    }

    if (filters.cap) {
      list = list.filter(([, stock]) => {
        const cap = Number(stock.marketCap || 0);

        if (filters.cap === "large") {
          return cap >= 500000000000;
        }

        if (filters.cap === "mid") {
          return (
            cap >= 50000000000 &&
            cap < 500000000000
          );
        }

        return cap < 50000000000;
      });
    }

    return list;
  }, [stocks, filters]);


  // ===============================
  // STATS
  // ===============================

  const stats = useMemo(() => {
    const values = Object.values(stocks);

    const total = values.length;

    const gainers = values.filter(
      (stock) => stock.change > 0
    ).length;

    const losers = values.filter(
      (stock) => stock.change < 0
    ).length;

    const avgVol = total
      ? Math.round(
          values.reduce(
            (sum, stock) =>
              sum + (stock.volume || 0),
            0
          ) /
            total /
            1000000
        )
      : 0;

    return {
      total,
      gainers,
      losers,
      avgVol
    };
  }, [stocks]);


  // ===============================
  // PORTFOLIO VALUE
  // ===============================

  const portfolioValue = useMemo(() => {
    return portfolio.holdings.reduce(
      (total, holding) => {
        const stock = stocks[holding.symbol];

        if (!stock) return total;

        return (
          total +
          stock.price * holding.quantity
        );
      },
      0
    );
  }, [portfolio, stocks]);


  const totalPortfolioValue =
    portfolio.cashBalance + portfolioValue;


  // ===============================
  // EXPORT CSV
  // ===============================

  const exportData = () => {
    const rows = [
      [
        "Company",
        "Symbol",
        "Sector",
        "Price",
        "Change",
        "% Change",
        "Volume",
        "Market Cap",
        "Exchange"
      ]
    ];

    Object.values(stocks).forEach((stock) => {
      rows.push([
        stock.name,
        stock.symbol,
        stock.sector,
        stock.price.toFixed(2),
        stock.change.toFixed(2),
        stock.changePercent,
        stock.volume || 0,
        stock.marketCap,
        stock.exchange
      ]);
    });

    const csv = rows
      .map((row) =>
        row
          .map((value) =>
            `"${String(value).replaceAll(
              '"',
              '""'
            )}"`
          )
          .join(",")
      )
      .join("\n");

    const url = URL.createObjectURL(
      new Blob([csv], {
        type: "text/csv"
      })
    );

    const a = document.createElement("a");

    a.href = url;

    a.download = `techstock-data-${
      new Date()
        .toISOString()
        .split("T")[0]
    }.csv`;

    a.click();

    URL.revokeObjectURL(url);
  };


  // ===============================
  // RENDER
  // ===============================

  return (
    <div className="dashboard">

      {/* ========================= */}
      {/* MESSAGE */}
      {/* ========================= */}

      {message && (
        <div
          style={{
            position: "fixed",
            top: "80px",
            right: "25px",
            zIndex: 9999,
            padding: "14px 20px",
            borderRadius: "8px",
            background:
              messageType === "error"
                ? "#ef4444"
                : "#10b981",
            color: "#fff",
            fontWeight: "600",
            boxShadow:
              "0 10px 30px rgba(0,0,0,.3)"
          }}
        >
          <i
            className={`fas ${
              messageType === "error"
                ? "fa-exclamation-circle"
                : "fa-check-circle"
            }`}
            style={{ marginRight: "8px" }}
          />

          {message}
        </div>
      )}


      {/* ========================= */}
      {/* NAVBAR */}
      {/* ========================= */}

      <nav className="topbar">
        <div className="nav-content">

          <div className="brand">
            <i className="fas fa-chart-line brand-icon" />

            <span className="brand-text">
              TechStock
            </span>

            <span className="brand-accent">
              PRO
            </span>
          </div>


          <div className="nav-controls">

            <div className="market-status">

              <div
                className={`status-dot ${
                  marketStatus === "ERROR"
                    ? ""
                    : "active"
                }`}
              />

              <span>
                {marketStatus}
              </span>

            </div>


            <button
              className="btn-icon"
              onClick={() => {
                const nextTheme =
                  theme === "dark"
                    ? "light"
                    : "dark";

                setTheme(nextTheme);

                localStorage.setItem(
                  "theme",
                  nextTheme
                );
              }}
            >
              <i
                className={`fas ${
                  theme === "light"
                    ? "fa-moon"
                    : "fa-palette"
                }`}
              />
            </button>

          </div>

        </div>
      </nav>


      {/* ========================= */}
      {/* MARKET TICKER */}
      {/* ========================= */}

      <div className="market-strip">
        <div className="market-ticker">

          {marketIndices.map((index) => (
            <div
              className="ticker-item"
              key={index.name}
            >
              <span className="ticker-name">
                {index.name}
              </span>

              <span className="ticker-price">
                {index.value.toLocaleString()}
              </span>

              <span
                className={`ticker-change ${
                  index.change >= 0
                    ? "positive"
                    : "negative"
                }`}
              >
                {index.change >= 0
                  ? "▲"
                  : "▼"}{" "}
                {Math.abs(index.change)}
              </span>
            </div>
          ))}

        </div>
      </div>


      {/* ========================= */}
      {/* MAIN GRID */}
      {/* ========================= */}

      <div className="main-grid">


        {/* ======================= */}
        {/* SIDEBAR */}
        {/* ======================= */}

        <aside className="sidebar">


          {/* WATCHLIST */}

          <div className="panel watchlist-panel">

            <div className="panel-header">

              <h3>
                <i className="fas fa-star" />
                {" "}Watchlist
              </h3>

              <span className="value-badge">
                ₹
                {watchlist
                  .reduce(
                    (sum, symbol) =>
                      sum +
                      (stocks[symbol]?.price ||
                        0),
                    0
                  )
                  .toLocaleString(
                    undefined,
                    {
                      maximumFractionDigits: 0
                    }
                  )}
              </span>

            </div>


            <div className="panel-body">

              <div className="watchlist-items">

                {watchlist.length === 0 ? (

                  <div className="empty-state">
                    <i className="fas fa-star" />

                    <p>
                      Your watchlist is empty
                    </p>
                  </div>

                ) : (

                  watchlist.map((symbol) => {

                    const stock =
                      stocks[symbol];

                    if (!stock) return null;

                    return (
                      <div
                        className="watchlist-item"
                        key={symbol}
                        onClick={() =>
                          setSelectedStock(
                            symbol
                          )
                        }
                      >

                        <div className="stock-info">

                          <h4>
                            {stock.name}
                          </h4>

                          <div className="stock-meta">
                            {stock.symbol} •{" "}
                            {stock.sector}
                          </div>

                        </div>


                        <div className="stock-data">

                          <div className="stock-price">
                            ₹
                            {stock.price.toFixed(
                              2
                            )}
                          </div>

                          <div
                            className={`stock-change ${
                              stock.change >= 0
                                ? "positive"
                                : "negative"
                            }`}
                          >
                            {stock.change >= 0
                              ? "+"
                              : ""}
                            {stock.change.toFixed(
                              2
                            )}
                          </div>

                        </div>


                        <button
                          className="btn-remove"
                          onClick={(event) => {
                            event.stopPropagation();

                            removeFromWatchlist(
                              symbol
                            );
                          }}
                        >
                          <i className="fas fa-times" />
                        </button>

                      </div>
                    );
                  })

                )}

              </div>

            </div>

          </div>


          {/* SEARCH */}

          <div className="panel search-panel">

            <div className="panel-header">

              <h3>
                <i className="fas fa-search" />
                {" "}Search
              </h3>

            </div>


            <div className="panel-body">

              <div className="search-container">

                <input
                  value={filters.search}
                  onChange={(event) =>
                    setFilters((previous) => ({
                      ...previous,
                      search:
                        event.target.value
                    }))
                  }
                  placeholder="Search stocks..."
                  className="search-input"
                />

                <i className="fas fa-search search-icon" />

              </div>


              <div className="filters">

                <select
                  value={filters.sector}
                  onChange={(event) =>
                    setFilters((previous) => ({
                      ...previous,
                      sector:
                        event.target.value
                    }))
                  }
                  className="filter-select"
                >

                  <option value="">
                    All Sectors
                  </option>

                  {[...new Set(
                    Object.values(stocks).map(
                      (stock) =>
                        stock.sector
                    )
                  )].map((sector) => (
                    <option
                      key={sector}
                      value={sector}
                    >
                      {sector}
                    </option>
                  ))}

                </select>


                <select
                  value={filters.cap}
                  onChange={(event) =>
                    setFilters((previous) => ({
                      ...previous,
                      cap:
                        event.target.value
                    }))
                  }
                  className="filter-select"
                >

                  <option value="">
                    All Cap
                  </option>

                  <option value="large">
                    Large Cap
                  </option>

                  <option value="mid">
                    Mid Cap
                  </option>

                  <option value="small">
                    Small Cap
                  </option>

                </select>

              </div>

            </div>

          </div>


          {/* PORTFOLIO */}

          <div className="panel">

            <div className="panel-header">

              <h3>
                <i className="fas fa-wallet" />
                {" "}Portfolio
              </h3>

            </div>


            <div className="panel-body">

              <div
                style={{
                  display: "grid",
                  gap: "12px"
                }}
              >

                <div>
                  <small>
                    Cash Balance
                  </small>

                  <h3>
                    ₹
                    {portfolio.cashBalance.toLocaleString(
                      undefined,
                      {
                        maximumFractionDigits: 2
                      }
                    )}
                  </h3>
                </div>


                <div>
                  <small>
                    Holdings Value
                  </small>

                  <h3>
                    ₹
                    {portfolioValue.toLocaleString(
                      undefined,
                      {
                        maximumFractionDigits: 2
                      }
                    )}
                  </h3>
                </div>


                <div>
                  <small>
                    Total Portfolio
                  </small>

                  <h3>
                    ₹
                    {totalPortfolioValue.toLocaleString(
                      undefined,
                      {
                        maximumFractionDigits: 2
                      }
                    )}
                  </h3>
                </div>

              </div>

            </div>

          </div>


          {/* STATS */}

          <div className="panel stats-panel">

            <div className="panel-header">

              <h3>
                <i className="fas fa-chart-pie" />
                {" "}Stats
              </h3>

            </div>


            <div className="panel-body">

              <div className="stats-grid">

                <div className="stat-item">
                  <div className="stat-value">
                    {stats.total}
                  </div>

                  <div className="stat-label">
                    Total
                  </div>
                </div>


                <div className="stat-item gain">
                  <div className="stat-value">
                    {stats.gainers}
                  </div>

                  <div className="stat-label">
                    Gainers
                  </div>
                </div>


                <div className="stat-item loss">
                  <div className="stat-value">
                    {stats.losers}
                  </div>

                  <div className="stat-label">
                    Losers
                  </div>
                </div>


                <div className="stat-item">
                  <div className="stat-value">
                    {stats.avgVol}M
                  </div>

                  <div className="stat-label">
                    Avg Vol
                  </div>
                </div>

              </div>

            </div>

          </div>

        </aside>


        {/* ======================= */}
        {/* MAIN CONTENT */}
        {/* ======================= */}

        <main className="main-content">


          {/* CONTROLS */}

          <div className="controls-bar">

            <div className="chart-controls">

              {[
                ["line", "fa-chart-line"],
                ["area", "fa-chart-area"],
                ["bar", "fa-chart-bar"]
              ].map(([type, icon]) => (

                <button
                  key={type}
                  className={`ctrl-btn ${
                    chartType === type
                      ? "active"
                      : ""
                  }`}
                  onClick={() =>
                    setChartType(type)
                  }
                >
                  <i
                    className={`fas ${icon}`}
                  />
                </button>

              ))}

            </div>


            <div className="action-controls">

              <button
                className="btn-primary"
                onClick={refresh}
                disabled={updating}
              >

                <i className="fas fa-sync-alt" />

                <span>
                  {updating
                    ? "Updating..."
                    : "Refresh"}
                </span>

              </button>


              <button
                className="btn-secondary"
                onClick={exportData}
              >
                <i className="fas fa-download" />
              </button>

            </div>

          </div>


          {/* CHARTS */}

          <div className="charts-grid">

            {watchlist.length === 0 ? (

              <div className="empty-state">

                <i className="fas fa-chart-line" />

                <p>
                  Add stocks to see live charts
                </p>

              </div>

            ) : (

              watchlist.map((symbol) => {

                const stock =
                  stocks[symbol];

                if (!stock) return null;

                return (
                  <StockChart
                    key={`${symbol}-${chartType}`}
                    name={stock.name}
                    data={stock}
                    company={stock}
                    type={chartType}
                  />
                );

              })

            )}

          </div>


          {/* STOCK TABLE */}

          <div className="panel table-panel">

            <div className="panel-header">

              <h3>
                <i className="fas fa-list" />
                {" "}Stock Listings
              </h3>

              <span className="count-badge">
                {filteredStocks.length}
              </span>

            </div>


            <div className="panel-body">

              <div className="table-container">

                <table className="data-table">

                  <thead>

                    <tr>
                      <th>Company</th>
                      <th>Price</th>
                      <th>Change</th>
                      <th>Volume</th>
                      <th>Cap</th>
                      <th>Action</th>
                    </tr>

                  </thead>


                  <tbody>

                    {filteredStocks.map(
                      ([symbol, stock]) => {

                        const added =
                          watchlist.includes(
                            symbol
                          );

                        return (

                          <tr
                            className="stock-row"
                            key={symbol}
                            onClick={() =>
                              setSelectedStock(
                                symbol
                              )
                            }
                          >

                            <td>

                              <div className="company-name">
                                {stock.name}
                              </div>

                              <div className="company-symbol">
                                {stock.symbol} •{" "}
                                {stock.sector}
                              </div>

                            </td>


                            <td className="price-cell">
                              ₹
                              {stock.price.toFixed(
                                2
                              )}
                            </td>


                            <td
                              className={`change-cell ${
                                stock.change >= 0
                                  ? "positive"
                                  : "negative"
                              }`}
                            >

                              {stock.change >= 0
                                ? "+"
                                : ""}
                              {stock.change.toFixed(
                                2
                              )}

                              <br />

                              <small>
                                (
                                {
                                  stock.changePercent
                                }
                                )
                              </small>

                            </td>


                            <td className="volume-cell">
                              {(
                                (stock.volume ||
                                  0) /
                                1000000
                              ).toFixed(1)}
                              M
                            </td>


                            <td>
                              {formatMarketCap(
                                stock.marketCap
                              )}
                            </td>


                            <td>

                              <button
                                className="btn-add"
                                disabled={added}
                                onClick={(event) => {
                                  event.stopPropagation();

                                  if (!added) {
                                    addToWatchlist(
                                      symbol
                                    );
                                  }
                                }}
                              >

                                <i
                                  className={`fas ${
                                    added
                                      ? "fa-check"
                                      : "fa-plus"
                                  }`}
                                />

                                {" "}

                                {added
                                  ? "Added"
                                  : "Add"}

                              </button>

                            </td>

                          </tr>

                        );
                      }
                    )}

                  </tbody>

                </table>

              </div>

            </div>

          </div>


          {/* TRANSACTION HISTORY */}

          <div className="panel table-panel">

            <div className="panel-header">

              <h3>
                <i className="fas fa-history" />
                {" "}Transaction History
              </h3>

              <span className="count-badge">
                {transactions.length}
              </span>

            </div>


            <div className="panel-body">

              {transactions.length === 0 ? (

                <div className="empty-state">

                  <i className="fas fa-receipt" />

                  <p>
                    No transactions yet
                  </p>

                </div>

              ) : (

                <div className="table-container">

                  <table className="data-table">

                    <thead>

                      <tr>
                        <th>Type</th>
                        <th>Stock</th>
                        <th>Quantity</th>
                        <th>Price</th>
                        <th>Total</th>
                        <th>Date</th>
                      </tr>

                    </thead>


                    <tbody>

                      {transactions.map(
                        (transaction) => (

                          <tr
                            key={
                              transaction._id
                            }
                          >

                            <td>

                              <span
                                className={
                                  transaction.type ===
                                  "BUY"
                                    ? "positive"
                                    : "negative"
                                }
                              >
                                {transaction.type}
                              </span>

                            </td>


                            <td>
                              {transaction.symbol}
                            </td>


                            <td>
                              {transaction.quantity}
                            </td>


                            <td>
                              ₹
                              {transaction.price.toFixed(
                                2
                              )}
                            </td>


                            <td>
                              ₹
                              {transaction.totalAmount.toLocaleString(
                                undefined,
                                {
                                  maximumFractionDigits: 2
                                }
                              )}
                            </td>


                            <td>
                              {new Date(
                                transaction.createdAt
                              ).toLocaleString()}
                            </td>

                          </tr>

                        )
                      )}

                    </tbody>

                  </table>

                </div>

              )}

            </div>

          </div>

        </main>

      </div>


      {/* ========================= */}
      {/* STOCK MODAL */}
      {/* ========================= */}

      {selectedStock &&
        stocks[selectedStock] && (

          <StockModal
            name={selectedStock}
            data={stocks[selectedStock]}
            company={stocks[selectedStock]}
            inWatchlist={watchlist.includes(
              selectedStock
            )}
            onClose={() =>
              setSelectedStock(null)
            }
            onAdd={addToWatchlist}
            onRemove={removeFromWatchlist}
            onBuy={buyStock}
            onSell={sellStock}
            portfolio={portfolio}
            tradeLoading={tradeLoading}
          />

        )}


      {/* ========================= */}
      {/* LOADING */}
      {/* ========================= */}

      {loading && (

        <div className="loading-screen">

          <div className="loader">

            <div className="loader-inner" />

          </div>

          <p>
            Connecting to TechStock API...
          </p>

        </div>

      )}

    </div>
  );
}


// =====================================
// STOCK CHART
// =====================================

function StockChart({
  name,
  data,
  company,
  type
}) {

  const ref = useRef(null);

  useEffect(() => {

    if (!ref.current || !data) return;

    const ctx =
      ref.current.getContext("2d");

    const color =
      data.change >= 0
        ? "#10b981"
        : "#ef4444";

    let gradient = null;

    if (type === "area") {

      gradient =
        ctx.createLinearGradient(
          0,
          0,
          0,
          250
        );

      gradient.addColorStop(
        0,
        color + "40"
      );

      gradient.addColorStop(
        1,
        color + "00"
      );
    }


    const history =
      data.history || [
        {
          time: new Date().toLocaleTimeString(),
          price: data.price
        }
      ];


    const chart = new Chart(ctx, {

      type:
        type === "area"
          ? "line"
          : type,

      data: {

        labels: history.map(
          (item) => item.time
        ),

        datasets: [

          {

            label: `${name} Price`,

            data: history.map(
              (item) => item.price
            ),

            borderColor: color,

            backgroundColor:
              type === "area"
                ? gradient
                : type === "bar"
                ? color + "80"
                : color + "20",

            borderWidth:
              type === "bar"
                ? 0
                : 2,

            fill:
              type === "area",

            tension:
              type === "line" ||
              type === "area"
                ? 0.4
                : 0,

            pointRadius:
              type === "bar"
                ? 0
                : 1

          }

        ]

      },

      options: {

        responsive: true,

        maintainAspectRatio: false,

        plugins: {

          legend: {
            display: false
          },

          tooltip: {
            mode: "index",
            intersect: false
          }

        },

        scales: {

          x: {
            grid: {
              color: "#2d3748"
            },

            ticks: {
              color: "#6b7280",
              font: {
                family: "JetBrains Mono",
                size: 10
              }
            }

          },

          y: {

            beginAtZero: false,

            grid: {
              color: "#2d3748"
            },

            ticks: {

              color: "#6b7280",

              font: {
                family: "JetBrains Mono",
                size: 10
              },

              callback: (value) =>
                "₹" +
                Number(value).toFixed(0)

            }

          }

        }

      }

    });


    return () => chart.destroy();

  }, [data, type, name]);


  return (

    <div className="chart-card fade-in">

      <div className="chart-header">

        <div>

          <h4 className="chart-title">
            {name}
          </h4>

          <div className="chart-symbol">
            {company.symbol} •{" "}
            {company.sector}
          </div>

        </div>


        <div>

          <div className="chart-price">
            ₹
            {data.price.toFixed(2)}
          </div>

          <div
            className={`chart-change ${
              data.change >= 0
                ? "positive"
                : "negative"
            }`}
          >

            {data.change >= 0
              ? "+"
              : ""}

            {data.change.toFixed(2)}

            {" "}

            (
            {data.changePercent}
            )

          </div>

        </div>

      </div>


      <div className="chart-container">

        <canvas ref={ref} />

      </div>

    </div>
  );
}


// =====================================
// STOCK MODAL
// =====================================

function StockModal({
  name,
  data,
  company,
  inWatchlist,
  onClose,
  onAdd,
  onRemove,
  onBuy,
  onSell,
  portfolio,
  tradeLoading
}) {

  const [quantity, setQuantity] =
    useState(1);


  const holding =
    portfolio.holdings.find(
      (item) =>
        item.symbol === data.symbol
    );


  return (

    <div
      className="modal show"
      onClick={(event) => {

        if (
          event.target ===
          event.currentTarget
        ) {
          onClose();
        }

      }}
    >

      <div className="modal-content">


        {/* HEADER */}

        <div className="modal-header">

          <h2>
            {name} ({company.symbol})
          </h2>

          <button
            className="modal-close"
            onClick={onClose}
          >
            &times;
          </button>

        </div>


        {/* BODY */}

        <div className="modal-body">


          {/* PRICE */}

          <div className="price-overview">

            <div className="current-price">

              <h2>
                ₹
                {data.price.toFixed(2)}
              </h2>

              <div
                className={`price-change ${
                  data.change >= 0
                    ? "positive"
                    : "negative"
                }`}
              >

                {data.change >= 0
                  ? "▲"
                  : "▼"}

                {" "}

                {data.change >= 0
                  ? "+"
                  : ""}

                {data.change.toFixed(2)}

                {" "}

                ({data.changePercent})

              </div>

            </div>

          </div>


          <div className="details-grid">


            {/* CHART */}

            <div className="chart-section">

              <h3>
                <i className="fas fa-chart-line" />
                {" "}Price Chart
              </h3>

              <div className="modal-chart-container">

                <ModalChart
                  name={name}
                  data={data}
                />

              </div>

            </div>


            {/* INFORMATION */}

            <div className="info-section">


              <div className="metrics-grid">

                <Metric
                  label="Volume"
                  value={(
                    data.volume || 0
                  ).toLocaleString()}
                />

                <Metric
                  label="Market Cap"
                  value={formatMarketCap(
                    data.marketCap
                  )}
                />

                <Metric
                  label="Sector"
                  value={data.sector}
                />

                <Metric
                  label="Exchange"
                  value={data.exchange}
                />

              </div>


              {/* TRADING */}

              <div
                style={{
                  marginTop: "20px",
                  padding: "18px",
                  border:
                    "1px solid var(--border-color)",
                  borderRadius: "10px"
                }}
              >

                <h3>
                  <i className="fas fa-exchange-alt" />
                  {" "}Trade {data.symbol}
                </h3>


                <div
                  style={{
                    display: "flex",
                    gap: "10px",
                    alignItems: "center",
                    marginTop: "12px",
                    flexWrap: "wrap"
                  }}
                >

                  <input
                    type="number"
                    min="1"
                    value={quantity}
                    onChange={(event) =>
                      setQuantity(
                        Math.max(
                          1,
                          Number(
                            event.target
                              .value
                          )
                        )
                      )
                    }
                    style={{
                      width: "100px",
                      padding: "10px",
                      borderRadius: "6px",
                      border:
                        "1px solid var(--border-color)",
                      background:
                        "var(--bg-secondary)",
                      color:
                        "var(--text-primary)"
                    }}
                  />


                  <button
                    className="btn-primary"
                    disabled={tradeLoading}
                    onClick={() =>
                      onBuy(
                        data.symbol,
                        quantity
                      )
                    }
                  >

                    <i className="fas fa-shopping-cart" />

                    {" "}

                    {tradeLoading
                      ? "Processing..."
                      : "BUY"}

                  </button>


                  <button
                    className="btn-secondary"
                    disabled={
                      tradeLoading ||
                      !holding ||
                      holding.quantity <
                        quantity
                    }
                    onClick={() =>
                      onSell(
                        data.symbol,
                        quantity
                      )
                    }
                  >

                    <i className="fas fa-hand-holding-usd" />

                    {" "}SELL

                  </button>

                </div>


                <div
                  style={{
                    marginTop: "12px",
                    fontSize: "13px",
                    color:
                      "var(--text-secondary)"
                  }}
                >

                  You own:{" "}

                  <strong>
                    {holding?.quantity || 0}
                  </strong>

                  {" "}share(s)

                </div>

              </div>


              {/* COMPANY INFO */}

              <div className="company-info">

                <h3>
                  <i className="fas fa-building" />
                  {" "}Stock Information
                </h3>


                <div className="info-grid">

                  <Info
                    label="Symbol:"
                    value={data.symbol}
                  />

                  <Info
                    label="Exchange:"
                    value={data.exchange}
                  />

                  <Info
                    label="Sector:"
                    value={data.sector}
                  />

                  <Info
                    label="Last Updated:"
                    value={new Date(
                      data.lastUpdated
                    ).toLocaleString()}
                  />

                </div>

              </div>


              {/* WATCHLIST */}

              <div className="modal-actions">

                <button
                  className={`btn-action ${
                    inWatchlist
                      ? "btn-remove-modal"
                      : ""
                  }`}
                  onClick={() => {

                    if (inWatchlist) {
                      onRemove(name);
                    } else {
                      onAdd(name);
                    }

                  }}
                >

                  <i
                    className={`fas ${
                      inWatchlist
                        ? "fa-star"
                        : "fa-plus"
                    }`}
                  />

                  {" "}

                  {inWatchlist
                    ? "Remove from Watchlist"
                    : "Add to Watchlist"}

                </button>

              </div>

            </div>

          </div>

        </div>

      </div>

    </div>
  );
}


