// =====================================
// MODAL CHART
// =====================================

function ModalChart({
  name,
  data
}) {

  const ref = useRef(null);


  useEffect(() => {

    if (!ref.current) return;

    const ctx =
      ref.current.getContext("2d");

    const color =
      data.change >= 0
        ? "#10b981"
        : "#ef4444";


    const gradient =
      ctx.createLinearGradient(
        0,
        0,
        0,
        250
      );

    gradient.addColorStop(
      0,
      color + "40"
    );

    gradient.addColorStop(
      1,
      color + "00"
    );


    const history =
      data.history || [
        {
          time: new Date().toLocaleTimeString(),
          price: data.price
        }
      ];


    const chart = new Chart(ctx, {

      type: "line",

      data: {

        labels: history.map(
          (item) => item.time
        ),

        datasets: [

          {

            label: `${name} Price`,

            data: history.map(
              (item) => item.price
            ),

            borderColor: color,

            backgroundColor: gradient,

            borderWidth: 3,

            fill: true,

            tension: 0.4,

            pointRadius: 2,

            pointHoverRadius: 8,

            pointBackgroundColor: color,

            pointBorderColor: "#fff",

            pointBorderWidth: 2

          }

        ]

      },

      options: {

        responsive: true,

        maintainAspectRatio: false,

        interaction: {
          intersect: false,
          mode: "index"
        },

        plugins: {

          legend: {
            display: false
          },

          tooltip: {

            displayColors: false,

            callbacks: {

              title: (items) =>
                `${name} - ${items[0].label}`,

              label: (item) =>
                `Price: ₹${item.parsed.y.toFixed(
                  2
                )}`

            }

          }

        },

        scales: {

          x: {

            grid: {
              color: "#2d3748"
            },

            ticks: {
              color: "#6b7280"
            }

          },

          y: {

            beginAtZero: false,

            grid: {
              color: "#2d3748"
            },

            ticks: {

              color: "#6b7280",

              callback: (value) =>
                "₹" +
                Number(value).toFixed(0)

            }

          }

        }

      }

    });


    return () => chart.destroy();

  }, [data, name]);


  return <canvas ref={ref} />;
}


// =====================================
// MARKET CAP FORMAT
// =====================================

function formatMarketCap(value) {

  const number = Number(value || 0);

  if (number >= 1000000000000) {
    return (
      "₹" +
      (number / 1000000000000).toFixed(2) +
      "T"
    );
  }

  if (number >= 1000000000) {
    return (
      "₹" +
      (number / 1000000000).toFixed(2) +
      "B"
    );
  }

  if (number >= 1000000) {
    return (
      "₹" +
      (number / 1000000).toFixed(2) +
      "M"
    );
  }

  return "₹" + number.toLocaleString();
}


